                  <input type="text" id="hf-custom-range" value="${pe(I.customRange)}" placeholder="e.g. 2-5, 8" style="width: 100%; height: 26px; padding: 0 6px; font-size: 11.5px; border: 1px solid #94A3B8; border-radius: 4px; box-sizing: border-box;">
                </div>

